with parsed as (select id, service, host, latency_ms, status_code, context, context['version'] as version, get_json_object(payload_json, '$.user.tier') as user_tier, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, shiftright(status_code, 2) as status_code_high, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs where service != 'auth') select *, avg(latency_ms) over (partition by tier order by status_code asc, id asc rows between 6 preceding and current row) as latency_ms_avg_6, last_value(version, true) over (partition by tier, service order by latency_ms asc, id asc rows between unbounded preceding and current row) as last_known_version from parsed
